    kg_json = {"e32_ceo_kg_learning_strategy_feedback": "operations/knowledge_graph/e32_ceo_kg_learning_strategy_feedback.json", "e32_ceo_kg_promotion_candidates_update": "operations/knowledge_graph/e32_ceo_kg_promotion_candidates_update.json", "e32_ceo_kg_read_model_update": "operations/knowledge_graph/e32_ceo_kg_read_model_update.json"}
